/**
 * ui-helpers.ts — shared UI helpers used by both the static and Databricks bundles.
 *
 * Used by:
 *   - src/static/taskpane/databricks.ts (static host)
 *   - src/databricks/actions.ts         (injected Databricks script)
 *   - src/databricks/taskpane.ts        (injected Databricks script)
 *
 * Uses replaceChildren() + textContent (not innerHTML) to prevent XSS via
 * user-controlled data (email/username from the API response).
 */

type AuthStatus = "idle" | "pending" | "success" | "error";

const ICON_MAP: Record<AuthStatus, string> = {
  idle: "ms-Icon--Signin",
  pending: "ms-Icon--Sync",
  success: "ms-Icon--CheckMark",
  error: "ms-Icon--ErrorBadge",
};

export function updateAuthStatus(status: AuthStatus, message: string): void {
  const statusEl = document.getElementById("auth-status");
  if (!statusEl) return;

  statusEl.className = `auth-status auth-status-${status}`;

  // Build the status element safely — avoid innerHTML to prevent XSS via
  // user-controlled data (email/username from the API response).
  statusEl.replaceChildren();

  const icon = document.createElement("i");
  icon.className = `ms-Icon ${ICON_MAP[status]} ms-font-xl`;

  const textSpan = document.createElement("span");
  textSpan.className = "auth-status-text";
  textSpan.textContent = message;

  statusEl.appendChild(icon);
  statusEl.appendChild(textSpan);
}
