/**
 * log-helpers.ts — shared localStorage log persistence.
 *
 * Used by both:
 *   - src/static/taskpane/taskpane.ts (static host — writes before Databricks script loads)
 *   - src/databricks/log.ts (Databricks bundle — reads + renders to DOM)
 *
 * Both webpack bundles compile separately but share this source module at
 * build time, ensuring both sides use the same localStorage key and entry
 * format.
 */

export const LOG_STORAGE_KEY = "taskpane-log";

export type LogLevel = "error" | "info" | "success" | "reasoning" | "debug";

export interface LogEntry {
  level: LogLevel;
  message: string;
  time: string;
  /**
   * Monotonic id unique among all entries ever persisted in this task
   * pane session. Lets a streaming updater locate its own entry even when
   * other entries are appended while it streams (e.g. several batches
   * streaming reasoning at once) — an array index would go stale.
   */
  id: number;
}

// localStorage slot holding the next entry id to allocate. Kept in its
// own slot (not derived from the entries) so allocating an id never has
// to scan the log array.
const LOG_NEXT_ID_STORAGE_KEY = "taskpane-log-next-id";

// Fallback counter for the (rare) case where localStorage is unavailable
// (quota exceeded, privacy mode) — only has to be unique within this
// page load, since nothing can be persisted then anyway.
let memoryNextLogEntryId = 1;

/**
 * Allocates the next log entry id.
 *
 * The counter is read from localStorage on every allocation instead of
 * being cached in a module variable: the static and Databricks bundles
 * each embed their own copy of this module into the same task pane page,
 * so an in-memory counter would exist twice and each copy would go
 * stale as the other bundle logs. Reading the persisted counter each
 * time keeps ids unique across both bundles. The read-increment-write
 * is synchronous, so it can't interleave with another allocation.
 *
 * When the counter slot is missing (first run after this scheme, or
 * cleared browser data), it is seeded once from the highest id already
 * in the log so ids stay monotonic across the upgrade. If localStorage
 * is unavailable, falls back to the in-memory counter.
 */
function allocateLogEntryId(): number {
  try {
    const stored = localStorage.getItem(LOG_NEXT_ID_STORAGE_KEY);
    let next = stored === null ? 0 : Number(stored);

    if (!(next >= 1)) {
      let max = 0;
      for (const entry of getLogEntries()) {
        if (typeof entry.id === "number" && entry.id > max) {
          max = entry.id;
        }
      }
      next = max + 1;
    }

    localStorage.setItem(LOG_NEXT_ID_STORAGE_KEY, String(next + 1));
    return next;
  } catch {
    return memoryNextLogEntryId++;
  }
}

/**
 * Reads all log entries from localStorage. Returns an empty array if
 * storage is empty or corrupted (corrupted data is cleared).
 */
export function getLogEntries(): LogEntry[] {
  try {
    const stored = localStorage.getItem(LOG_STORAGE_KEY);
    if (!stored) return [];
    const entries = JSON.parse(stored) as LogEntry[];
    if (!Array.isArray(entries)) {
      localStorage.removeItem(LOG_STORAGE_KEY);
      return [];
    }
    return entries;
  } catch {
    localStorage.removeItem(LOG_STORAGE_KEY);
    return [];
  }
}

/**
 * Persists a log entry to localStorage. Works without any DOM — safe to
 * call before the task pane UI is injected.
 */
export function persistLogEntry(level: LogLevel, message: string): void {
  const entry: LogEntry = {
    level,
    message,
    id: allocateLogEntryId(),
    // 24-hour time keeps the timestamp narrow — the log's time column
    // is rendered on two lines (date over time), and "18:46:26" fits
    // where "6:46:26 PM" would wrap.
    time: `${new Date().toLocaleDateString()} ${new Date().toLocaleTimeString(undefined, {
      hour12: false,
      hour: "2-digit",
      minute: "2-digit",
      second: "2-digit",
      hourCycle: "h23",
    })}`,
  };
  const entries = getLogEntries();
  entries.push(entry);
  localStorage.setItem(LOG_STORAGE_KEY, JSON.stringify(entries));
}

/**
 * Clears all log entries from localStorage.
 *
 * The id counter is deliberately NOT reset: a streaming updater
 * (createStreamingLogEntry in log.ts) can still hold an id allocated
 * before the clear, and re-allocating those ids for new entries would
 * make the updater write its stream into the wrong entry.
 */
export function clearLogEntries(): void {
  localStorage.removeItem(LOG_STORAGE_KEY);
}
