/**
 * storage-keys.ts — shared localStorage key constants.
 *
 * Used by both:
 *   - src/static/dialog/auth.ts (static host — writes after SSO)
 *   - src/databricks/actions.ts (injected script — reads config)
 *
 * These must stay in sync because the static bundle and Databricks bundle
 * are compiled separately and cannot share runtime code. Importing from
 * this file ensures both sides reference the same string values.
 */

export const TOKEN_STORAGE_KEY = "databricks-access-token";
export const TOKEN_USER_KEY = "databricks-user-info";
