/**
 * Shared authentication logic for the static host.
 *
 * Provides the dialog-based SSO flow and token storage. Used by
 * databricks.ts to authenticate and inject the Databricks-served task pane.
 *
 * This module has NO side effects (no top-level Office.onReady, no DOM
 * manipulation).
 */

import { TOKEN_STORAGE_KEY, TOKEN_USER_KEY } from "../../shared/storage-keys";
import type { UserInfo } from "../../shared/storage-helpers";

// ---------------------------------------------------------------------------
// Constants & interfaces
// ---------------------------------------------------------------------------

/**
 * The URL of the redirect page on the static host (same domain as the task
 * pane). Office's displayDialogAsync requires an absolute HTTPS URL on the
 * same domain as the host page. This page immediately redirects to the
 * Databricks App auth-dialog page, which is on a different domain.
 */
// Derive the redirect URL from the current document location so it works
// on any host — including GitHub Pages, which serves from a subpath
// (https://<user>.github.io/<repo>/) where window.location.origin alone
// would drop the /<repo>/ prefix.
const LOGIN_REDIRECT_URL = new URL("login-redirect.html", window.location.href).href;

interface TokenResponse {
  accessToken: string;
  user: string | null;
  email: string | null;
  username: string | null;
}

// UserInfo is imported from shared/storage-helpers.ts (see imports above).

// ---------------------------------------------------------------------------
// Dialog-based authentication
// ---------------------------------------------------------------------------

/**
 * Opens the auth dialog so the user can authenticate with Databricks.
 *
 * The Databricks Apps auth gate requires a full browser redirect.
 * The task pane's embedded webview can't handle that redirect, so we open
 * a separate dialog window via the Office Dialog API. The dialog page
 * (auth-dialog.html) loads, Databricks auth completes in the real browser,
 * then the dialog fetches /api/token and sends the result back here via
 * messageParent().
 *
 * @throws Error if the dialog fails or the user closes it.
 */
function fetchAccessTokenViaDialog(): Promise<TokenResponse> {
  return new Promise((resolve, reject) => {
    Office.context.ui.displayDialogAsync(
      // Open the redirect page on the SAME domain as the host (static
      // host). Office requires the first dialog page to be same-domain.
      // The redirect page immediately navigates to the Databricks App
      // auth-dialog page, where auth completes in the real browser.
      LOGIN_REDIRECT_URL,
      { height: 60, width: 30, displayInIframe: false },
      (asyncResult) => {
        if (asyncResult.status === Office.AsyncResultStatus.Failed) {
          reject(new Error(`Dialog failed to open: ${asyncResult.error.message}`));
          return;
        }

        const dialog = asyncResult.value;

        // Set up a timeout — if auth takes too long, reject
        const timeout = setTimeout(() => {
          dialog.close();
          reject(new Error("Authentication timed out. Please try again."));
        }, 120000); // 2 minutes

        dialog.addEventHandler(Office.EventType.DialogMessageReceived, (result) => {
          clearTimeout(timeout);
          dialog.close();

          try {
            const msgResult = result as { message: string };
            const data = JSON.parse(msgResult.message);

            if (data.error) {
              reject(new Error(data.error));
              return;
            }

            if (data.success && data.token) {
              resolve(data.token as TokenResponse);
              return;
            }

            reject(new Error("Unexpected response from auth dialog."));
          } catch (e) {
            reject(new Error(`Failed to parse auth response: ${(e as Error).message}`));
          }
        });

        dialog.addEventHandler(Office.EventType.DialogEventReceived, (result) => {
          clearTimeout(timeout);
          dialog.close();
          const errResult = result as { error: number };
          reject(new Error(`Dialog closed unexpectedly (error ${errResult.error}).`));
        });
      }
    );
  });
}

// ---------------------------------------------------------------------------
// Core auth flow (no UI)
// ---------------------------------------------------------------------------

/**
 * Authenticates with Databricks via the Office Dialog API and stores the
 * token, user info, and OpenAI config in localStorage.
 *
 * This is the core logic — it does NOT update any UI. The task pane
 * (databricks.ts) wraps this with status updates.
 *
 * @returns The token response (also stored in localStorage).
 * @throws Error if the dialog fails or the user closes it.
 */
export async function connectDatabricks(): Promise<TokenResponse> {
  const tokenResponse = await fetchAccessTokenViaDialog();

  // Store the token and user info
  localStorage.setItem(TOKEN_STORAGE_KEY, tokenResponse.accessToken);
  const userInfo: UserInfo = {
    user: tokenResponse.user,
    email: tokenResponse.email,
    username: tokenResponse.username,
  };
  localStorage.setItem(TOKEN_USER_KEY, JSON.stringify(userInfo));

  // OpenAI config is fetched separately by refreshConfig() from /api/config,
  // so it stays decoupled from the auth token flow.

  return tokenResponse;
}
