/**
 * storage-helpers.ts — shared localStorage read helpers and types.
 *
 * Used by both:
 *   - src/static/dialog/auth.ts (static host)
 *   - src/databricks/actions.ts (injected Databricks script)
 *
 * Both webpack bundles compile separately, so they can't share runtime
 * code — but they CAN share this source module at build time.
 */

import { TOKEN_STORAGE_KEY, TOKEN_USER_KEY } from "./storage-keys";

// ---------------------------------------------------------------------------
// Shared types
// ---------------------------------------------------------------------------

export interface UserInfo {
  user: string | null;
  email: string | null;
  username: string | null;
}

// ---------------------------------------------------------------------------
// Read helpers
// ---------------------------------------------------------------------------

export function getAccessToken(): string | null {
  return localStorage.getItem(TOKEN_STORAGE_KEY);
}

export function getUserInfo(): UserInfo | null {
  const raw = localStorage.getItem(TOKEN_USER_KEY);
  if (!raw) return null;
  try {
    return JSON.parse(raw) as UserInfo;
  } catch {
    return null;
  }
}
