/**
 * databricks.ts — Databricks authentication + task pane script injection.
 *
 * Handles the dialog-based SSO flow and fetching/injecting the
 * Databricks-served task pane script. The injected script replaces the
 * auth shell with the full task pane UI.
 */

import { connectDatabricks } from "../dialog/auth";
import { getAccessToken, getUserInfo } from "../../shared/storage-helpers";
import { DATABRICKS_APP_URL } from "../../shared/constants";
import { updateAuthStatus } from "../../shared/ui-helpers";

// ---------------------------------------------------------------------------
// Script injection
// ---------------------------------------------------------------------------

/**
 * Fetches the Databricks task pane JS bundle via /api/taskpane-script
 * (authenticated with the Bearer token) and injects it as an inline script.
 * The injected script builds the full task pane UI.
 */
export async function injectDatabricksTaskpane(): Promise<void> {
  const token = getAccessToken();
  if (!token) {
    throw new Error("No access token after authentication.");
  }

  try {
    updateAuthStatus("pending", "Fetching task pane script…");
    const response = await fetch(`${DATABRICKS_APP_URL}/api/taskpane-script`, {
      headers: { Authorization: `Bearer ${token}` },
    });

    if (!response.ok) {
      throw new Error(`Failed to load task pane script (HTTP ${response.status})`);
    }

    const code = await response.text();

    if (!code || code.length < 100) {
      throw new Error(`Task pane script is empty or too short (${code.length} chars)`);
    }

    updateAuthStatus("pending", `Injecting script (${code.length} chars)…`);

    // Inject via a blob URL so CSP doesn't need unsafe-inline.
    const blob = new Blob([code], { type: "application/javascript" });
    const blobUrl = URL.createObjectURL(blob);
    const script = document.createElement("script");

    script.src = blobUrl;

    // Wait for the script to load AND for the injected IIFE to signal
    // readiness by setting window.__databricksReady = true.  A blob script
    // with invalid content (e.g. HTML) will fire onload but never set the
    // flag, so we use a timeout to detect this silent failure.
    await new Promise<void>((resolve, reject) => {
      const timeout = setTimeout(() => {
        URL.revokeObjectURL(blobUrl);
        reject(
          new Error(
            "Task pane script loaded but did not signal readiness within 10s. " +
              "It may be stale or invalid — try redeploying the Databricks App."
          )
        );
      }, 10000);

      script.onload = () => {
        URL.revokeObjectURL(blobUrl);
        // Give the IIFE a tick to run (it sets __databricksReady synchronously)
        setTimeout(() => {
          if (window.__databricksReady) {
            clearTimeout(timeout);
            resolve();
          } else {
            clearTimeout(timeout);
            reject(
              new Error(
                "Task pane script loaded but did not initialize. " +
                  "The Databricks App may be serving a stale build — try redeploying."
              )
            );
          }
        }, 100);
      };

      script.onerror = () => {
        URL.revokeObjectURL(blobUrl);
        clearTimeout(timeout);
        reject(new Error("Failed to execute the Databricks task pane script."));
      };

      document.head.appendChild(script);
    });
  } catch (error) {
    throw new Error(`Failed to inject task pane script: ${(error as Error).message}`);
  }
}

// ---------------------------------------------------------------------------
// Auth + inject flow
// ---------------------------------------------------------------------------

/**
 * Connects to Databricks, then fetches and injects the Databricks-served
 * task pane script. The injected script replaces the auth shell with the
 * full task pane UI.
 */
export async function connectAndInject(): Promise<void> {
  updateAuthStatus("pending", "Opening sign-in dialog…");

  try {
    const tokenResponse = await connectDatabricks();

    const displayName = tokenResponse.email || tokenResponse.username || tokenResponse.user || "Authenticated";

    // Fetch and inject the Databricks-served task pane script.
    // Don't set "success" until injection actually succeeds — if it fails,
    // the error status from injectDatabricksTaskpane will be visible.
    updateAuthStatus("pending", `Signed in as ${displayName}, loading task pane…`);
    await injectDatabricksTaskpane();
    updateAuthStatus("success", `Signed in as ${displayName}`);
  } catch (error) {
    updateAuthStatus("error", (error as Error).message);
  }
}

/**
 * If a cached token exists, tries to inject the Databricks task pane
 * directly. If the token is expired or missing, triggers the full
 * auth flow (dialog).
 */
export async function verifySessionOrConnect(): Promise<void> {
  const cachedToken = getAccessToken();
  if (cachedToken) {
    const userInfo = getUserInfo();
    const displayName = userInfo?.email || userInfo?.username || userInfo?.user || "Authenticated";

    updateAuthStatus("pending", `Signed in as ${displayName}, loading task pane…`);

    try {
      await injectDatabricksTaskpane();
      updateAuthStatus("success", `Signed in as ${displayName}`);
    } catch {
      // Token expired or injection failed — authenticate
      await connectAndInject();
    }
  } else {
    connectAndInject();
  }
}
