/**
 * taskpane.ts — orchestrator for the GitHub Pages task pane.
 *
 * This is the webpack entry point. It coordinates:
 *   - databricks.ts → Databricks auth + task pane script injection
 *
 * The command action (checkPunctuation) is a thin wrapper: if the Databricks
 * script hasn't been injected yet (user not authenticated), it triggers
 * the auth flow first, then calls the Databricks-side checkPunctuation via
 * the window global it exposes.
 */

// Globals exposed by the injected Databricks task pane script.
declare global {
  interface Window {
    __databricksReady?: boolean;
    __checkPunctuation?: () => Promise<void>;
    __checkTerminology?: () => Promise<void>;
  }
}

import { connectAndInject, verifySessionOrConnect } from "./databricks";
import { persistLogEntry } from "../../shared/log-helpers";

// ---------------------------------------------------------------------------
// Command action — "Punctuation" button
// ---------------------------------------------------------------------------

async function checkPunctuation(event: Office.AddinCommands.Event): Promise<void> {
  // If the Databricks script hasn't been injected yet, trigger auth first.
  // The Databricks script exposes window.__checkPunctuation once loaded.
  if (!window.__databricksReady) {
    await connectAndInject();
  }

  // If still not ready after auth attempt, log an error.
  if (!window.__checkPunctuation) {
    persistLogEntry("error", "Authentication required to check punctuation.");
  } else {
    await window.__checkPunctuation();
  }

  event.completed();
}

// ---------------------------------------------------------------------------
// Command action — "Terminology" button
// ---------------------------------------------------------------------------

async function checkTerminology(event: Office.AddinCommands.Event): Promise<void> {
  // If the Databricks script hasn't been injected yet, trigger auth first.
  // The Databricks script exposes window.__checkTerminology once loaded.
  if (!window.__databricksReady) {
    await connectAndInject();
  }

  // If still not ready after auth attempt, log an error.
  if (!window.__checkTerminology) {
    persistLogEntry("error", "Authentication required to check terminology.");
  } else {
    await window.__checkTerminology();
  }

  event.completed();
}

// ---------------------------------------------------------------------------
// Initialization
// ---------------------------------------------------------------------------

Office.onReady(async (info) => {
  if (info.host !== Office.HostType.Word) return;

  // Register the command actions
  Office.actions.associate("checkPunctuation", checkPunctuation);
  Office.actions.associate("checkTerminology", checkTerminology);

  // Show the task pane body
  document.getElementById("app-body")!.style.display = "flex";

  // Wire up the sign-in button — starts the Databricks auth flow.
  // The static shell always shows this icon (it's the logged-out state).
  // The Databricks-injected UI replaces it with the refresh icon.
  const signInBtn = document.getElementById("sign-in-btn");
  if (signInBtn) {
    signInBtn.onclick = () => {
      connectAndInject();
    };
  }

  // Listen for re-auth requests from the injected Databricks script
  window.addEventListener("databricks-reauth", () => {
    connectAndInject();
  });

  // If we have a cached token, verify it and inject the task pane.
  // Otherwise, trigger the sign-in dialog automatically.
  await verifySessionOrConnect();
});
